// Sample RESPONSE transformer script.
// Modified from version originally generated by Claude.
// For learning purposes only.

(function(inputs) {
    /* inputs structure: {
        prompt_data: object,
        request_data: object,
        response_body: string,
        response_headers: string
    } */
    var responseBody = JSON.parse(inputs.response_body);
    // gs.info("HF response: " + inputs.response_body);

    var responseTexts = [];

    if (responseBody.choices && responseBody.choices.length > 0 &&
        responseBody.choices[0].message) {
        responseTexts.push(responseBody.choices[0].message.content);
    } else {
        gs.error("Unexpected HF response structure: " + inputs.response_body);
    }

    return responseTexts;
})(inputs);